SELECT 
    l.l_shipmonth,
    SUM(Sum(l_extendedprice * (1 - l.DISCOUNT))) AS revenue,
    SUM(
        (
            SUM(
                (
                    SUM(
                        (
                            CASE WHEN l.l_shipdate IS NULL THEN 0 ELSE 1 END 
                            WHEN l.l_shipdate >= '1995-01-01' AND l.l_shipdate < '1996-01-01' THEN 1
                            ELSE 0
                        )
                    )
                )
            )
        )
    )
ORDER BY l.l_shipmonth
